<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2).'/api/_core/bootstrap.php';
require_once dirname(__DIR__, 2).'/api/_core/order_filler_diagnostics.php';
if(empty($_SERVER['HTTPS']) || strtolower((string)$_SERVER['HTTPS'])==='off')api_error('HTTPS is required.',403,'https_required');
$authorization=existing_guarded_access([PERMISSION_DEVELOPER],ACCESS_TOKEN_SCOPE_DIAGNOSTICS);
if($authorization===null && ($_SERVER['REQUEST_METHOD']??'GET')==='POST')$authorization=authorize_guarded_access([PERMISSION_DEVELOPER],ACCESS_TOKEN_SCOPE_DIAGNOSTICS,true);
if($authorization===null)render_access_token_prompt('Order Filler diagnostics','Sign in as a developer/superuser or use a permitted access token.','./');
$locale=(string)($_GET['lang']??'en-US');
try{OrderFillerDiagnostics::basename('time',$locale);}catch(InvalidArgumentException){api_error('Invalid language/region.',422,'invalid_locale');}
header('Cache-Control: no-store');
header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'");
header('Referrer-Policy: no-referrer');
?>
